#include <string>
#include <vector>
#include <unordered_set>

class Solution {
public:
    std::vector<std::string> partitionString(std::string s) {
        std::unordered_set<std::string> seen;
        std::vector<std::string> ans;
        int n = s.size();
        int i = 0;

        while (i < n) {
            std::string curr = "";
            int j = i;
            while (j < n) {
                curr += s[j];
                if (seen.find(curr) == seen.end()) break;
                j++;
            }
            seen.insert(curr);
            ans.push_back(curr);
            i = j + 1;
        }

        return ans;
    }
};

import java.util.*;

class Solution {
    public List<String> partitionString(String s) {
        Set<String> seen = new HashSet<>();
        List<String> ans = new ArrayList<>();
        int n = s.length();
        int i = 0;

        while (i < n) {
            StringBuilder curr = new StringBuilder();
            int j = i;
            while (j < n) {
                curr.append(s.charAt(j));
                if (!seen.contains(curr.toString())) break;
                j++;
            }
            String segment = curr.toString();
            seen.add(segment);
            ans.add(segment);
            i = j + 1;
        }

        return ans;
    }
}

