var partitionString = function(s) {
    const seen = new Set();
    const ans = [];
    const n = s.length;
    let i = 0;

    while (i < n) {
        let curr = "";
        let j = i;
        while (j < n) {
            curr += s[j];
            if (!seen.has(curr)) break;
            j++;
        }
        seen.add(curr);
        ans.push(curr);
        i = j + 1;
    }

    return ans;
